<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue';
import {beadHeight,beadProgress,paletteColors,paintBeads,type BeadData} from '../lib/beads';
const props=defineProps<{data:BeadData}>();const emit=defineEmits<{(e:'close'):void}>();
const viewport=ref<HTMLElement|null>(null),canvas=ref<HTMLCanvasElement|null>(null),dialog=ref<HTMLElement|null>(null),zoom=ref(1),grid=ref(false);
const width=computed(()=>props.data.size*24*zoom.value),height=computed(()=>beadHeight(props.data)*24*zoom.value);
let previousFocus:HTMLElement|null=null,previousOverflow='';
const dragging=ref(false);
let drag:{id:number;x:number;y:number;left:number;top:number}|null=null;
function startDrag(e:PointerEvent){const v=viewport.value;if(!v||!e.isPrimary||e.button!==0||drag)return;if(v.scrollWidth<=v.clientWidth&&v.scrollHeight<=v.clientHeight)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:v.scrollLeft,top:v.scrollTop};dragging.value=true;v.setPointerCapture(e.pointerId);e.preventDefault();}
function moveDrag(e:PointerEvent){const v=viewport.value;if(!v||!drag||drag.id!==e.pointerId)return;v.scrollLeft=drag.left+drag.x-e.clientX;v.scrollTop=drag.top+drag.y-e.clientY;e.preventDefault();}
function stopDrag(){const v=viewport.value,id=drag?.id;drag=null;dragging.value=false;if(v&&id!==undefined&&v.hasPointerCapture(id))v.releasePointerCapture(id);}
function draw(){const c=canvas.value;if(!c)return;const d=props.data,cell=24;c.width=d.size*cell;c.height=beadHeight(d)*cell;const ctx=c.getContext('2d')!;ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);if(grid.value)paintBeads(ctx,d.pixels,d.size,cell,false,true,d.palette,beadHeight(d));else{const colors=paletteColors(d.palette);d.pixels.forEach((color,i)=>{if(color){ctx.fillStyle=colors[color].hex;ctx.fillRect(i%d.size*cell,Math.floor(i/d.size)*cell,cell,cell);}});}}
function fit(){stopDrag();const v=viewport.value;if(!v)return;zoom.value=Math.max(.05,Math.min(1,(v.clientWidth-24)/(props.data.size*24),(v.clientHeight-24)/(beadHeight(props.data)*24)));v.scrollTop=v.scrollLeft=0;}
async function scale(factor:number){stopDrag();const v=viewport.value;if(!v)return;const before=zoom.value,x=(v.scrollLeft+v.clientWidth/2)/before,y=(v.scrollTop+v.clientHeight/2)/before;zoom.value=Math.max(.05,Math.min(3,before*factor));await nextTick();v.scrollLeft=x*zoom.value-v.clientWidth/2;v.scrollTop=y*zoom.value-v.clientHeight/2;}
function keys(e:KeyboardEvent){if(e.key==='Escape'){e.preventDefault();emit('close');}if(e.key==='Tab'){const items=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),[tabindex="0"]')||[]),first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}
watch(grid,draw);watch(()=>props.data,()=>{draw();fit();});
onMounted(async()=>{previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();draw();fit();dialog.value?.querySelector<HTMLButtonElement>('button')?.focus();window.addEventListener('resize',fit);});
onBeforeUnmount(()=>{document.body.style.overflow=previousOverflow;window.removeEventListener('resize',fit);previousFocus?.focus({preventScroll:true});});
</script>
<template>
<view class="bead-preview-backdrop" @click.self="emit('close')" @keydown="keys">
 <component :is="'section'" ref="dialog" class="bead-preview-dialog" role="dialog" aria-modal="true" aria-labelledby="bead-preview-title">
  <view class="preview-heading"><view><text class="preview-eyebrow">摸鱼成果鉴赏大会</text><text id="bead-preview-title">{{data.name}}</text></view><component :is="'button'" class="preview-button preview-close" @click="emit('close')" aria-label="关闭预览">×</component></view>
  <component :is="'div'" ref="viewport" class="preview-viewport" :class="{dragging}" @pointerdown="startDrag" @pointermove="moveDrag" @pointerup="stopDrag" @pointercancel="stopDrag" @lostpointercapture="stopDrag" tabindex="0" aria-label="拼豆大图，放大后按住拖动查看"><component :is="'canvas'" ref="canvas" :style="{width:width+'px',height:height+'px'}" :aria-label="data.name+'拼豆成果'"/></component>
  <view class="preview-controls"><component :is="'button'" class="preview-button" @click="scale(1/1.4)" :disabled="zoom<=.05" aria-label="缩小">−</component><text>{{Math.round(zoom*100)}}%</text><component :is="'button'" class="preview-button" @click="scale(1.4)" :disabled="zoom>=3" aria-label="放大">＋</component><component :is="'button'" class="preview-button" @click="fit">适合屏幕</component><component :is="'button'" class="preview-button" :class="{selected:grid}" :aria-pressed="grid" @click="grid=!grid">{{grid?'隐藏色号':'网格 / 色号'}}</component></view>
  <text class="preview-note">{{data.size}} × {{beadHeight(data)}} · 已拼 {{beadProgress(data).filled}} 颗豆 · 放大后按住图片拖动查看</text>
 </component>
</view>
</template>
<style scoped>
.bead-preview-backdrop{position:fixed;inset:0;z-index:1900;background:#20271dc4;backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box}.bead-preview-dialog{width:920px;max-width:100%;max-height:94dvh;overflow:auto;box-sizing:border-box;background:#fafaf3;border:1px solid #e1e5d6;border-radius:22px;padding:20px;color:#748365}.preview-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:14px}.preview-heading>view{min-width:0}.preview-eyebrow{display:block;font-size:10px;color:#a89ab5;margin-bottom:7px}#bead-preview-title{display:block;font-size:17px;font-weight:600;overflow-wrap:anywhere}.bead-preview-dialog .preview-button{background:#eaf0df;border:1px solid #dbe3ce;border-radius:9px;color:#758b5c;font-size:12px;padding:8px 11px;cursor:pointer;line-height:1.5}.bead-preview-dialog .preview-button:disabled{opacity:.4;cursor:default}.bead-preview-dialog .preview-button:focus-visible{outline:2px solid #8eab70;outline-offset:2px}.bead-preview-dialog .preview-close{font-size:23px;padding:2px 12px;flex-shrink:0}.preview-viewport{height:60dvh;min-height:180px;overflow:auto;background:#fff;border:1px solid #dce1d5;border-radius:10px;padding:12px;box-sizing:border-box;overscroll-behavior:contain;touch-action:none;user-select:none;cursor:grab}.preview-viewport.dragging{cursor:grabbing}.preview-viewport canvas{display:block;margin:auto;image-rendering:pixelated}.preview-controls{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:14px}.preview-controls>text{min-width:36px;text-align:center;font-size:11px}.preview-controls .preview-button.selected{background:#7f9667;color:white}.preview-note{display:block;font-size:11px;margin-top:12px;color:#a0a88f}@media(max-width:600px){.bead-preview-backdrop{padding:10px}.bead-preview-dialog{padding:14px;border-radius:16px}.preview-viewport{height:56dvh}.preview-controls{gap:5px}.bead-preview-dialog .preview-button{font-size:11px;padding:8px}.preview-note{font-size:10px}}
</style>
